846	/**
847	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
848	 *
849	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
850	 * "a customer can never delete a platform archive" invariant is enforced rather
851	 * than merely intended. It re-checks protection against the live hypervisor for
852	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
853	 * volid cannot slip past it. Every uncertain outcome throws.
854	 */
855	export async function deleteBackup(client: any, volid: string): Promise<void> {
856	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
857	  // anything else keeps a malformed or path-traversing volid from ever reaching
858	  // the API, and keeps this function honest about what it operates on.
859	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
860	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
861	
862	  const registry = await protectedVolids();
863	  if (registry === null) {
864	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
865	  }
866	  if (registry.has(volid)) {
867	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
868	  }
869	
870	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
871	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
872	  // here means we do not know whether this is a platform archive, so we stop.
873	  let info: any;
874	  try {
875	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
876	  } catch (e) {
877	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
878	  }
879	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
880	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
881	  }
882	
883	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
884	}
