886	/**
887	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
888	 * belong to that customer, deleting the older ones (best-effort per file, oldest
889	 * first). Runs after every successful customer backup, and from the standalone
890	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
891	 *
892	 * Platform archives are excluded from the delete set AND from the retention
893	 * count. Counting them would be its own bug: with keep = 2, three platform
894	 * archives of a vmid would make every customer archive "older than the newest
895	 * two" and delete all of the customer's backups instead.
896	 */
897	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
898	  // `keep` decides how many of a customer's restore points survive, so it is
899	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
900	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
901	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
902	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
903	  // the way past. Fail closed instead — an over-retained archive costs disk, a
904	  // missing one costs the customer their only restore point.
905	  if (!Number.isInteger(keep) || keep < 1) {
906	    throw new Error(
907	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
908	        `retention must be a whole number of at least 1.`
909	    );
910	  }
911	
912	  const registry = await protectedVolids();
913	  if (registry === null) {
914	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
915	    // recoverable; deleting the platform's only copy of a VM is not.
916	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
917	    return 0;
918	  }
919	
920	  const forVmid = await listBackupsOn(client, vmid);
921	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
922	  const mine = forVmid
923	    .filter((b) => !isPlatformArchive(b, registry))
924	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
925	
926	  if (shielded.length > 0) {
927	    console.log(
928	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
929	    );
930	  }
931	
932	  const toDelete = mine.slice(Math.max(0, keep));
933	  let deleted = 0;
934	  for (const b of toDelete) {
935	    try {
936	      await deleteBackup(client, b.volid!);
937	      deleted++;
938	    } catch (e) {
939	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
940	    }
941	  }
942	  return deleted;
943	}
