12	/**
13	 * Apply a customer's inbound firewall to their guest, idempotently.
14	 *
15	 * MECHANISM: guest-side iptables over SSH, mirroring how the platform already
16	 * reaches VMs (worker/claude.ts, worker/ssl.ts — sshpass + execFile ARRAY args,
17	 * never a shell string on the host). The Proxmox per-VM firewall API was the
18	 * alternative, but lib/proxmox.ts exposes only a generic REST client with no
19	 * firewall helper, and enabling it requires flipping cluster/node/NIC firewall
20	 * flags that interact with the existing NAT model — a far larger, riskier change
21	 * for guests that are already reachable as root over SSH. So: guest iptables.
22	 *
23	 * SAFETY: the reconcile SCRIPT is built by lib/firewall-rules.ts from VALIDATED,
24	 * structured fields only. Each DB row is re-run through `validateRule` here
25	 * (defence in depth) before it can contribute a line; a row that fails is skipped
26	 * and logged, never interpolated. Ports are integers, protocol/action are closed
27	 * enums, and the source CIDR is regex-validated + normalised — so no raw customer
28	 * string (the free-text `comment` least of all) ever reaches the guest shell.
29	 *
30	 * IDEMPOTENT: the script creates the NXEON_FW chain once, ensures INPUT jumps to
31	 * it once, then FLUSHES only that chain and rebuilds it — so re-running yields
32	 * identical kernel state and never accumulates stale rules or touches the
33	 * customer's own INPUT rules.
34	 *
35	 * ANTI-LOCKOUT: the baseline always accepts loopback, ESTABLISHED/RELATED and
36	 * tcp/22, so SSH stays reachable no matter what the customer configures, and the
37	 * default DROP is appended only when they have at least one ALLOW rule.
38	 */
39	export async function syncFirewall(job: Job): Promise<void> {
40	  const serverId = job.serverId;
41	  if (!serverId) throw new Error("syncFirewall: job has no serverId");
42	
43	  const server = await db.server.findUnique({
44	    where: { id: serverId },
45	    include: { firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] } },
46	  });
47	  if (!server) {
48	    // Row is gone (server deleted); the cascade removed its rules too. Nothing to do.
49	    console.log(`[fw] server ${serverId} not found — skipping firewall sync`);
50	    return;
51	  }
52	
53	  // Don't fight the lifecycle: a suspended/deleting/not-yet-provisioned VM has no
54	  // reachable guest to configure. The rules stay in the DB and re-apply on the
55	  // next sync once the server is steady again.
56	  if (["SUSPENDED", "DELETING", "PENDING", "PROVISIONING", "REINSTALLING", "STOPPED", "ERROR"].includes(server.status)) {
57	    console.log(`[fw] server ${serverId} status=${server.status} — deferring firewall sync`);
58	    return;
59	  }
60	
61	  // Re-validate every ENABLED row through the SAME gate the action used. A row
62	  // that somehow got into the DB malformed is dropped from the applied set (and
63	  // reported) rather than allowed to break the build.
64	  const validated: ValidatedRule[] = [];
65	  for (const r of server.firewallRules) {
66	    if (!r.enabled) continue;
67	    const result = validateRule({
68	      action: r.action,
69	      protocol: r.protocol,
70	      portFrom: r.portFrom,
71	      portTo: r.portTo,
72	      sourceCidr: r.sourceCidr,
73	    });
74	    if (!result.ok) {
75	      console.error(`[fw] server ${serverId} rule ${r.id} rejected at apply: ${result.error}`);
76	      continue;
77	    }
78	    validated.push(result.rule);
79	  }
80	
81	  const script = buildReconcileScript(validated);
82	
83	  if (SANDBOX) {
84	    console.log(`[fw] SANDBOX — would apply ${validated.length} rule(s) to ${server.hostname}:\n${script}`);
85	    return;
86	  }
87	
88	  const password = serverRootPassword(server);
89	  if (!server.ipAddress || !password) {
90	    throw new Error(`syncFirewall: server ${serverId} has no reachable IP or root password`);
91	  }
92	
93	  // sshpass + execFile ARRAY args: the script travels as a single-quoted payload
94	  // to `bash -c` on the guest; nothing here is assembled by a host shell.
95	  const args = [
96	    "-p",
97	    password,
98	    "ssh",
99	    "-o",
100	    "StrictHostKeyChecking=no",
101	    "-o",
102	    "UserKnownHostsFile=/dev/null",
103	    "-o",
104	    "ConnectTimeout=10",
105	    `root@${server.ipAddress}`,
106	    `bash -c ${shSingleQuote(script)}`,
107	  ];
108	
109	  try {
110	    await execFileAsync("sshpass", args, {
111	      timeout: CMD_TIMEOUT_MS,
112	      maxBuffer: 4 * 1024 * 1024,
113	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
114	    });
115	  } catch (e: any) {
116	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
117	    throw new Error(
118	      `syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — ${e?.killed ? "timed out" : `exit ${e?.code ?? "?"}`}` +
119	        (out ? `: ${out.slice(0, 400)}` : "")
120	    );
121	  }
122	
123	  console.log(`[fw] applied ${validated.length} rule(s) to ${server.hostname} (${FW_CHAIN})`);
124	}
