29	  if (total === 0) return;
30	  if (cursor >= total) cursor = 0;
31	
32	  const servers = await db.server.findMany({
33	    where,
34	    include: { dedicatedIp: { select: { address: true } }, user: { select: { email: true } } },
35	    orderBy: { id: "asc" },
36	    skip: cursor,
37	    take: BATCH_SIZE,
38	  });
39	  cursor += servers.length;
40	  if (servers.length < BATCH_SIZE) cursor = 0; // wrapped past the end of the table
41	
42	  for (const s of servers) {
43	    try {
44	      await withServerSsh(s, (conn) => exec(conn, "echo nxeon-health-ok", 10_000));
45	    } catch (e: any) {
46	      const msg = e?.message ?? String(e);
47	      console.error(`[ssh-health] ${s.hostname} (${s.id}) failed:`, msg);
48	      await notifyAdmins(
