255	/**
256	 * Track player join/leave events by comparing the live RCON player list against
257	 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
258	 *
259	 * For each RUNNING game server with a gamePlan:
260	 *   - NEW players (in RCON but no open session) → create a PlayerSession
261	 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
262	 *   - STILL ONLINE → no-op
263	 *
264	 * Per-server try/catch so one unreachable VM never blocks the sweep.
265	 */
266	export async function playerTrackingSweep(): Promise<void> {
267	  if (SANDBOX) return;
268	
269	  const servers = await db.server.findMany({
270	    where: { status: "RUNNING", gamePlanId: { not: null } },
271	    select: CONTROL_FIELDS,
272	  });
273	
274	  const now = new Date();
275	
276	  for (const server of servers) {
277	    try {
278	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
279	      if (!isGameFamily(fam)) continue;
280	      const spec = controlSpec(fam);
281	      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;
282	
283	      // Get online players via RCON
284	      const res = await withServerSsh(server as SftpServer, (conn) =>
285	        runRcon(conn, spec, spec.listCommand!)
286	      );
287	      if (!res.ok) continue;
288	      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
289	      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));
290	
291	      // Get open sessions for this server
292	      const openSessions = await db.playerSession.findMany({
293	        where: { serverId: server.id, leftAt: null },
294	      });
295	      const sessionByName = new Map(
296	        openSessions.map((s) => [s.playerName.toLowerCase(), s])
297	      );
298	
299	      // NEW players: in RCON but no open session
300	      for (const p of onlinePlayers) {
301	        if (!sessionByName.has(p.name.toLowerCase())) {
302	          await db.playerSession.create({
303	            data: { serverId: server.id, playerName: p.name },
304	          });
305	        }
306	      }
307	
308	      // DEPARTED players: open session but not in RCON
309	      for (const session of openSessions) {
310	        if (!onlineNames.has(session.playerName.toLowerCase())) {
311	          await db.playerSession.update({
312	            where: { id: session.id },
313	            data: { leftAt: now },
314	          });
315	        }
316	      }
317	    } catch (e) {
318	      // Per-server: one failure must not break the sweep
319	      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
320	    }
321	  }
322	}
